function transferByLegacy(
address sender,
address to,
uint256 amount
) public virtual returns (bool);

function transferFromByLegacy(
address sender,
address from,
address to,
uint256 amount
) public virtual returns (bool);

function approveByLegacy(
address sender,
address spender,
uint256 amount
) public virtual;
